#include <stdint.h>
#include "stm32f446xx.h"
#define BUFFER_SIZE (1000)
volatile uint16_t buffer[BUFFER_SIZE];
volatile uint8_t half_complete = 0;
volatile uint8_t full_complete = 0;

#if !defined(__SOFT_FP__) && defined(__ARM_FP)
  #warning __"FPU is not initialized, but the project is compiling for an FPU. Please initialize the FPU before use."__
#endif

void uart_write(int data){
    while(!(USART2->SR & (1U << 7))){}
    USART2->DR = (data & 0xFF);
}

void myPrintf(int data){
    char message[4];
    int i = 0;

    if(data == 0){
        uart_write('0');
        uart_write('\n');
        uart_write('\r');
        return;
    }

    while(data){
        message[i] = '0' + (data % 10);
        data /= 10;
        i++;
    }

    for(int j = i - 1; j >= 0; j--){
        uart_write(message[j]);
    }

    uart_write('\n');
    uart_write('\r');
}

void DMA2_Stream0_IRQHandler(void){
	if(DMA2->LISR & (1U << 4)){
		DMA2->LIFCR = (1U << 4);
		half_complete = 1;
	}

	if(DMA2->LISR & (1U << 5)){
		DMA2->LIFCR = (1U << 5);
		full_complete = 1;
	}

}

int main(void)
{
    RCC->AHB1ENR |= (1U << 0); //for pa0
    RCC->AHB1ENR |= (1U << 22); //for dma2
    RCC->APB1ENR |= (1U << 17); //for usart2
    RCC->APB2ENR |= (1U << 8); //for adc1

    GPIOA->MODER |= (0b11); //for pa0
    GPIOA->MODER |= (1U << 5) | (1U << 7); //for usart2
    GPIOA->MODER &= ~((1U << 4) | (1U << 6));
    GPIOA->AFR[0] |= (0b0111 << 8) | (0b0111 << 12); //pin to match usart2

    USART2->BRR = 16000000/115200; //how many ticks between each peek (~138)
    USART2->CR1 = 0; //clear ctrl
    USART2->CR1 |= (1U << 2) | (1U << 3); //enable rx and tx
    USART2->CR1 |= (1U << 13); //start usart2

    ADC1->SMPR2 |= (4U << 0); //set sampling time to 84 cycles
    ADC1->SQR3 = 0; //set first conversion channel to 0
    ADC1->SQR1 = 0; //set number of conversion channels to 1
    ADC1->CR2 |= (1U << 9);
    ADC1->CR2 |= (1U << 8);
    ADC1->CR2 |= (1U << 1);
    ADC1->CR2 |= (1U); //enable adc
    for(int volatile i = 0; i < 1000; i++);

    DMA2_Stream0->CR &= ~(1U);
    while(DMA2_Stream0->CR & (1U)){}
    DMA2->LIFCR = (0x0F7D0F7D);
    DMA2_Stream0->CR = 0;
    DMA2_Stream0->PAR = (uint32_t)&(ADC1->DR);
    DMA2_Stream0->M0AR = (uint32_t)buffer;
    DMA2_Stream0->NDTR = BUFFER_SIZE;
    DMA2_Stream0->CR &= ~((0b111 << 25) | (1U << 16) | (0b11 << 6) | (1U << 9) |(1U << 12) | (1U << 14));
    DMA2_Stream0->CR |= (1U << 17) | (1U << 10) | (1U << 11) | (1U << 13) | (1U << 8) | (1U << 4) | (1U << 3);
    DMA2_Stream0->FCR &= ~(1U << 2);

    NVIC->ISER[1] |= (1U << 24);
    DMA2_Stream0->CR |= (1U);


    ADC1->CR2 |= (1U << 30); //start conversion

    while(1){
    	if(half_complete){
    		half_complete = 0;
    		for(int i = 0; i < BUFFER_SIZE/2; i++){
    			myPrintf(buffer[i]);
    		}
    	}

    	if(full_complete){
    		full_complete = 0;
    	    for(int i = BUFFER_SIZE/2; i < BUFFER_SIZE; i++){
    	    	myPrintf(buffer[i]);
    	    }
    	 }
    }

}
